import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
export function showAcids(kind,t=null,reveal=false){const metal=kind==='metals';renderDiagram(metal?'Metal + acid → salt + gas':'Choose products from the reactant type',t?.reactants||'Use the supplied ions',`<div class="inventory-board"><span class="eyebrow">${metal?'ACID–METAL ACCOUNT':'NEUTRALISATION ACCOUNT'}</span><div class="inventory-row"><span>${t?.ions||'Acid supplies negative ion · other reactant supplies positive ion'}</span></div><div class="inventory-row"><span>${reveal?'Salt: '+t.salt:'Balance ion charges to build the salt'}</span></div><p class="inventory-outcome">${reveal?{hydrogen:'Other product: hydrogen',water:'Other product: water','water-co2':'Other products: water + CO₂'}[t.products]:'Predict the other products before checking'}</p><p class="diagram-caption">Symbolic product account, not experimental apparatus or a rate simulation.</p></div>`,metal?'METAL SCOPE: MG · ZN · FE':'OXIDE / HYDROXIDE / CARBONATE');}
